package app;import p.Base;public class Main {@SuppressWarnings({"rawtypes","unchecked"}) public static void main(String[] args){Leaf leaf=new Leaf("seed");Base<String> typed=leaf;Base<?> wildcard=(Base<?>)(Object)leaf;Base raw=wildcard;if(args[0].equals("alias")){raw.write("one");String first=typed.read();typed.write("two");Object second=wildcard.read();System.out.println(first+":"+second+":"+(wildcard==leaf)+":"+((Object)raw==(Object)typed)+":"+typed.reads+":"+typed.writes);}else if(args[0].equals("pollution")){raw.write(Integer.valueOf(7));Object broad=raw.read();String status="miss";try{String invalid=typed.read();}catch(ClassCastException expected){status="delayed";}raw.write("restored");System.out.println(broad+":"+status+":"+typed.read()+":"+typed.reads+":"+typed.writes);}else{Base<?>[] array=new Base<?>[]{leaf};Object[] objects=array;Base<Integer> ints=new Base<Integer>(Integer.valueOf(7));objects[0]=ints;Object broad=array[0].read();boolean accepted=array[0]==ints;String status="miss";try{objects[0]=new Other();}catch(ArrayStoreException expected){status="ase";}Base<?>[] cast=(Base<?>[])objects;objects[0]=null;System.out.println(broad+":"+accepted+":"+status+":"+(array[0]==null)+":"+(cast==array));}}}
